sap.ui.define([
  "sap/ui/test/Opa5",
  "sap/ui/test/matchers/AggregationLengthEquals",
  "sap/ui/test/matchers/PropertyStrictEquals"
], function (Opa5, AggregationLengthEquals, PropertyStrictEquals) {
  "use strict";

  Opa5.createPageObjects({
    onTheListPage: {
      assertions: {
        iShouldSeeProducts: function (count) {
          return this.waitFor({
            id: "productList",
            viewName: "List",
            matchers: new AggregationLengthEquals({ name: "items", length: count }),
            success: function () {
              Opa5.assert.ok(true, "The list shows " + count + " products");
            },
            errorMessage: "The product list does not have " + count + " items"
          });
        },
        iShouldSeeTheCreateButton: function () {
          return this.waitFor({
            viewName: "List",
            controlType: "sap.m.Button",
            matchers: new PropertyStrictEquals({ name: "text", value: "Create" }),
            success: function () {
              Opa5.assert.ok(true, "The Create button is visible");
            }
          });
        }
      }
    }
  });
});

// actions in the list page object
iSearchFor: function (text) {
  return this.waitFor({
    id: "searchField",
    viewName: "List",
    actions: new EnterText({ text: text, pressEnterKey: true }),
    errorMessage: "The search field was not found"
  });
},

iPressOnTheFirstProduct: function () {
  return this.waitFor({
    id: "productList",
    viewName: "List",
    actions: function (list) {
      new Press().executeOn(list.getItems()[0]);
    }
  });
},

// assertion in the detail page object
iShouldBeOnTheDetailPage: function () {
  return this.waitFor({
    id: "productTitle",
    viewName: "Detail",
    success: function () {
      Opa5.assert.ok(Opa5.getHashChanger().getHash().startsWith("products/"), "Navigated to the detail page");
    }
  });
}

sap.ui.define([
  "sap/ui/core/util/MockServer"
], function (MockServer) {
  "use strict";

  return {
    init: function () {
      const mockServer = new MockServer({
        rootUri: "/sap/opu/odata/sap/ZSHOP_SRV/"
      });

      MockServer.config({ autoRespond: true, autoRespondAfter: 300 });

      mockServer.simulate(sap.ui.require.toUrl("my/app/localService/metadata.xml"), {
        sMockdataBaseUrl: sap.ui.require.toUrl("my/app/localService/mockdata"),
        bGenerateMissingMockData: true
      });

      mockServer.start();
    }
  };
});

// simulate the function import POST /ApproveOrder?OrderID='...'
const requests = mockServer.getRequests();
requests.push({
  method: "POST",
  path: /ApproveOrder\?(.*)/,
  response: function (xhr) {
    xhr.respondJSON(200, {}, JSON.stringify({ d: { OrderID: "4711", Status: "A" } }));
    return true;
  }
});
mockServer.setRequests(requests);

// fill a server-side field after a create
mockServer.attachAfter(MockServer.HTTPMETHOD.POST, function (event) {
  const entry = event.getParameter("oEntity");
  entry.CreatedAt = new Date().toISOString();
}, "Products");

// configurable delay from the URL: ...?serverDelay=2000
const delay = Number(new URLSearchParams(window.location.search).get("serverDelay")) || 300;
MockServer.config({ autoRespond: true, autoRespondAfter: delay });

